   "    <div class=\"field\"><label>Descripción del proyecto</label><textarea id=\"mn_desc\" style=\"min-height:70px;\">${escapeHtml(d.descripcion_proyecto || '')}</textarea></div>\n    <div class=\"field\"><label>Fecha estimada de entrega</label><input type=\"date\" id=\"mn_entrega\" value=\"${d.fecha_entrega_proyecto || ''}\" /></div>\n    <div class=\"field\"><label>Resumen</label><textarea id=\"mn_resumen\" style=\"min-height:110px;\">${escapeHtml(d.resumen || '')}</textarea></div>\n    <div class=\"field\"><label>Puntos clave (uno por renglón)</label><textarea id=\"mn_puntos\" style=\"min-height:100px;\">${escapeHtml(lineas(d.puntos_clave))}</textarea></div>\n    <div class=\"field\"><label>Acuerdos (uno por renglón)</label><textarea id=\"mn_acuerdos\" style=\"min-height:80px;\">${escapeHtml(lineas(d.acuerdos))}</textarea></div>\n    <div class=\"field\"><label>Conclusión</label><textarea id=\"mn_conclusion\" style=\"min-height:70px;\">${escapeHtml(d.conclusion || '')}</textarea></div>\n    <label style=\"font-family:'JetBrains Mono',monospace; font-size:11px; font-weight:700; text-transform:uppercase;\">Tareas (cada una necesita al menos un responsable)</label>\n    <div id=\"mn_tareas\" style=\"margin-top:6px;\"></div>\n    <button class=\"secondary\" style=\"width:100%; margin:6px 0 12px;\" onclick=\"minutaAgregarTarea()\">+ Agregar tarea</button>\n    <div id=\"mn_error\" class=\"error-msg\"></div>\n    <div style=\"display:flex; gap:8px; flex-wrap:wrap; margin-top:8px;\">\n      <button class=\"secondary\" style=\"flex:1;\" onclick=\"minutaPdf(this)\">📄 Descargar PDF de la minuta</button>\n      <button class=\"primary\" style=\"flex:1;\" onclick=\"minutaCrearProyecto(this)\">✅ Crear proyecto con tareas</button>\n    </div>`;\n  _minutaPintarTareas();\n",
   "    <div class=\"field\"><label>Descripción del proyecto</label><textarea id=\"mn_desc\" style=\"min-height:70px;\">${escapeHtml(d.descripcion_proyecto || '')}</textarea></div>\n    <div class=\"field\"><label>Fecha estimada de entrega</label><input type=\"date\" id=\"mn_entrega\" value=\"${d.fecha_entrega_proyecto || ''}\" /></div>\n    <div class=\"field\"><label>Resumen</label><textarea id=\"mn_resumen\" style=\"min-height:110px;\">${escapeHtml(d.resumen || '')}</textarea></div>\n    <div class=\"field\"><label>Temas tratados (uno por renglón: \"Tema: lo que se dijo\")</label><textarea id=\"mn_temas\" style=\"min-height:120px;\">${escapeHtml((d.temas || []).map(t => (t.tema || '') + ': ' + (t.detalle || '')).join('\\n'))}</textarea></div>\n    <div class=\"field\"><label>Puntos clave (uno por renglón)</label><textarea id=\"mn_puntos\" style=\"min-height:100px;\">${escapeHtml(lineas(d.puntos_clave))}</textarea></div>\n    <div class=\"field\"><label>Acuerdos (uno por renglón: quién, qué y para cuándo)</label><textarea id=\"mn_acuerdos\" style=\"min-height:80px;\">${escapeHtml(lineas(d.acuerdos))}</textarea></div>\n    <div class=\"field\"><label>Pendientes y riesgos (uno por renglón)</label><textarea id=\"mn_riesgos\" style=\"min-height:60px;\">${escapeHtml(lineas(d.riesgos))}</textarea></div>\n    <div class=\"field\"><label>Conclusión</label><textarea id=\"mn_conclusion\" style=\"min-height:70px;\">${escapeHtml(d.conclusion || '')}</textarea></div>\n    <div class=\"field\"><label>Próxima reunión (opcional)</label><input id=\"mn_proxima\" value=\"${escapeHtml(d.proxima_reunion || '')}\" placeholder=\"Ej. 2026-10-27 a las 10:00 — revisión de cotizaciones\" /></div>\n    <label style=\"font-family:'JetBrains Mono',monospace; font-size:11px; font-weight:700; text-transform:uppercase;\">Tareas (cada una necesita al menos un responsable)</label>\n    <div id=\"mn_tareas\" style=\"margin-top:6px;\"></div>\n    <button class=\"secondary\" style=\"width:100%; margin:6px 0 12px;\" onclick=\"minutaAgregarTarea()\">+ Agregar tarea</button>\n    <div id=\"mn_error\" class=\"error-msg\"></div>\n    <div style=\"display:flex; gap:8px; flex-wrap:wrap; margin-top:8px;\">\n      <button class=\"secondary\" style=\"flex:1;\" onclick=\"minutaPdf(this)\">📄 Descargar PDF</button>\n      <button class=\"secondary\" style=\"flex:1;\" onclick=\"minutaWhatsApp(this)\">📲 Enviar por WhatsApp</button>\n      <button class=\"primary\" style=\"flex:1;\" onclick=\"minutaCrearProyecto(this)\">✅ Crear proyecto con tareas</button>\n    </div>`;\n  _minutaPintarTareas();\n"
